(4128592, 592734, 37444, '<td valign="top">lovely bokeh and composition - 7</td>', 'lovely bokeh and composition - 7', '2007-10-01 11:08:11.000000', NULL, 1),
(4128594, 591854, 70000, '<td valign="top">wow, I am waiting for the day I learn how to do this and then get a location to do it. I love the extra element of the tent it adds a lot to the composition</td>', 'wow, I am waiting for the day I learn how to do this and then get a location to do it. I love the extra element of the tent it adds a lot to the composition', '2007-10-01 11:08:33.000000', NULL, 1),
