(4129445, 591277, 3102, '<td valign="top">The timing of the shot is obviously great... I do wish it could have been in sharper focus, though.  A pass of a sharpening filter may have been enough to give it some more zip that way.  And I probably would have tried to level out the horizon a bit.</td>', 'The timing of the shot is obviously great... I do wish it could have been in sharper focus, though.  A pass of a sharpening filter may have been enough to give it some more zip that way.  And I probably would have tried to level out the horizon a bit.', '2007-10-01 13:53:30.000000', NULL, 1),
(4129447, 591979, 49109, '<td valign="top">yet another boring sunset (can''t believe it''s a sunrise). lacks of a subject.</td>', 'yet another boring sunset (can''t believe it''s a sunrise). lacks of a subject.', '2007-10-01 13:53:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4129449, 593163, 66597, '<td valign="top">The sidelighting is very pretty here, and nice DOF. Feel like the horse is ever so slightly OOF, though.</td>', 'The sidelighting is very pretty here, and nice DOF. Feel like the horse is ever so slightly OOF, though.', '2007-10-01 13:53:43.000000', NULL, 1),
(4129450, 592496, 3102, '<td valign="top">Very attractive arrangement!  The warm colors are very nice here.</td>', 'Very attractive arrangement!  The warm colors are very nice here.', '2007-10-01 13:54:14.000000', NULL, 1),
(4129451, 591886, 40088, '<td valign="top">nice photo, love the contrast and out of focus part</td>', 'nice photo, love the contrast and out of focus part', '2007-10-01 13:54:15.000000', NULL, 1),
(4129452, 592383, 66597, '<td valign="top">Very sharp with rich colors. I like the soft texture of the elk against the grass.</td>', 'Very sharp with rich colors. I like the soft texture of the elk against the grass.', '2007-10-01 13:54:22.000000', NULL, 1),
(4129454, 585018, 49109, '<td valign="top">focus is a bit off and DOF too shallow, only thing sharp is his nose</td>', 'focus is a bit off and DOF too shallow, only thing sharp is his nose', '2007-10-01 13:54:48.000000', NULL, 1),
(4129456, 593979, 66597, '<td valign="top">The DOF is just wonderful, as are the colors. If the one OOF sunflower weren''t in the foreground, this would earn top marks, but still very well done. 8.</td>', 'The DOF is just wonderful, as are the colors. If the one OOF sunflower weren''t in the foreground, this would earn top marks, but still very well done. 8.', '2007-10-01 13:55:16.000000', NULL, 1),
(4129459, 593916, 40088, '<td valign="top">nice, the shadow is a nice touch to an otherwise rather normal photo</td>', 'nice, the shadow is a nice touch to an otherwise rather normal photo', '2007-10-01 13:55:43.000000', NULL, 1),
(4129462, 592387, 66597, '<td valign="top">The skin tone is nice and the lighting is well done, but there''s something that feels almost hostile and posed instead of inviting here.</td>', 'The skin tone is nice and the lighting is well done, but there''s something that feels almost hostile and posed instead of inviting here.', '2007-10-01 13:55:56.000000', NULL, 1),
(4129463, 592872, 30982, '<td valign="top">So glad you included the person on the right.  Wonderful photograph.</td>', 'So glad you included the person on the right.  Wonderful photograph.', '2007-10-01 13:56:13.000000', NULL, 1),
(4129465, 593620, 49109, '<td valign="top">way too much clouds in front of possibly beautiful mountains</td>', 'way too much clouds in front of possibly beautiful mountains', '2007-10-01 13:56:22.000000', NULL, 1),
(4129467, 592093, 66597, '<td valign="top">The expression is very cute, but I don''t think the lighting is flattering - there''s too much blown out here.</td>', 'The expression is very cute, but I don''t think the lighting is flattering - there''s too much blown out here.', '2007-10-01 13:56:30.000000', NULL, 1),
(4129468, 584139, 40088, '<td valign="top">nice lighting and "random" lines and figures, 8</td>', 'nice lighting and "random" lines and figures, 8', '2007-10-01 13:56:35.000000', NULL, 1),
(4129470, 592387, 30982, '<td valign="top">Pretty good light and a nice setting for this.  I''m not sure about the angle of her head for the pose - seems a bit stiff, sorta.</td>', 'Pretty good light and a nice setting for this.  I''m not sure about the angle of her head for the pose - seems a bit stiff, sorta.', '2007-10-01 13:57:14.000000', NULL, 1),
(4129471, 587458, 35994, '<td valign="top">Nice composition, the water almost looks like a big whirlpool. Title is definitely fitting too.</td>', 'Nice composition, the water almost looks like a big whirlpool. Title is definitely fitting too.', '2007-10-01 13:57:19.000000', NULL, 1),
(4129473, 593995, 35994, '<td valign="top">Great closeup! Bokeh works really nice to make him stand out too.</td>', 'Great closeup! Bokeh works really nice to make him stand out too.', '2007-10-01 13:57:47.000000', NULL, 1),
(4129474, 591886, 3102, '<td valign="top">Excellent capture -- I guess that has two meanings!  Excellent capture by the bird, and by you!  One of a handful of 10s this time around.</td>', 'Excellent capture -- I guess that has two meanings!  Excellent capture by the bird, and by you!  One of a handful of 10s this time around.', '2007-10-01 13:57:48.000000', NULL, 1),
(4129475, 592674, 3102, '<td valign="top">One of my favorites this time around.  Excellent detail in the eyes!  - 10</td>', 'One of my favorites this time around.  Excellent detail in the eyes!  - 10', '2007-10-01 13:58:12.000000', NULL, 1),
(4129477, 593731, 35994, '<td valign="top">Looks a little grainy, but I think it kind of works for this shot. Some really nice colors in the petals.</td>', 'Looks a little grainy, but I think it kind of works for this shot. Some really nice colors in the petals.', '2007-10-01 13:58:30.000000', NULL, 1),
(4129478, 591854, 3102, '<td valign="top">I love these sorts of shots.  Very impressive!  One of a handful of 10s this time.</td>', 'I love these sorts of shots.  Very impressive!  One of a handful of 10s this time.', '2007-10-01 13:58:35.000000', NULL, 1),
