(4133697, 593564, 71951, '<td valign="top">Nicely done....looks like a perfect painting.</td>', 'Nicely done....looks like a perfect painting.', '2007-10-02 15:22:00.000000', NULL, 1),
(4133701, 584369, 71951, '<td valign="top">I like the perspective on this, I wish the guitar stood out a bit more though.</td>', 'I like the perspective on this, I wish the guitar stood out a bit more though.', '2007-10-02 15:23:13.000000', NULL, 1),
