(4136259, 593301, 23251, '<td valign="top">Wonderfull photo, I might have tried to keep the whole flower in without cropping it part way through.</td>', 'Wonderfull photo, I might have tried to keep the whole flower in without cropping it part way through.', '2007-10-03 05:47:28.000000', NULL, 1),
(4136261, 593579, 23251, '<td valign="top">Lovely photo and great colours in the sky.</td>', 'Lovely photo and great colours in the sky.', '2007-10-03 05:48:41.000000', NULL, 1),
