(4138038, 593934, 72782, '<td valign="top">great shot</td>', 'great shot', '2007-10-03 16:14:42.000000', NULL, 1),
(4138042, 589938, 72782, '<td valign="top">I would like to see more light inside the flower to bring out the texture more.</td>', 'I would like to see more light inside the flower to bring out the texture more.', '2007-10-03 16:15:54.000000', NULL, 1),
