(4138124, 591716, 32378, '<td valign="top">I really like this shot, except the wire running through her head.  I think advanced editing rules would let you clone that out.</td>', 'I really like this shot, except the wire running through her head.  I think advanced editing rules would let you clone that out.', '2007-10-03 16:45:20.000000', NULL, 1),
(4138133, 593991, 32378, '<td valign="top">Very well done..this pulls you right into her beautiful eyes.</td>', 'Very well done..this pulls you right into her beautiful eyes.', '2007-10-03 16:47:54.000000', NULL, 1),
