(4142447, 593435, 61012, '<td valign="top">Nice shot. I like the mirror-like reflection. Just a nitpick though... the colors seem a little washed out perhaps a bit more saturaton or a lighten the highlights but it''s quite nice as is</td>', 'Nice shot. I like the mirror-like reflection. Just a nitpick though... the colors seem a little washed out perhaps a bit more saturaton or a lighten the highlights but it''s quite nice as is', '2007-10-04 21:13:18.000000', NULL, 1),
(4142450, 593589, 63398, '<td valign="top">A little weak on the title/subject tie-in for me, but the exposure, lighting, detail, and conversion are all nicely done.</td>', 'A little weak on the title/subject tie-in for me, but the exposure, lighting, detail, and conversion are all nicely done.', '2007-10-04 21:14:26.000000', NULL, 1),
(4142453, 593631, 63398, '<td valign="top">Very nice image! Good work.....just the right amount of light and shadow''s to make this an awesome entry!</td>', 'Very nice image! Good work.....just the right amount of light and shadow''s to make this an awesome entry!', '2007-10-04 21:16:34.000000', NULL, 1),
(4142456, 592304, 63398, '<td valign="top">Very beautiful offering! Just perfect with the colors and light!</td>', 'Very beautiful offering! Just perfect with the colors and light!', '2007-10-04 21:17:48.000000', NULL, 1),
(4142462, 594051, 61012, '<td valign="top">Nice B&amp;W conversion and I like the use of a foreground element too.</td>', 'Nice B&W conversion and I like the use of a foreground element too.', '2007-10-04 21:21:43.000000', NULL, 1),
(4142469, 591620, 61012, '<td valign="top">I assume this is looking straight down into the box but I like the appearance that she''s deying gravity. I like the colors and tones of the shot.</td>', 'I assume this is looking straight down into the box but I like the appearance that she''s deying gravity. I like the colors and tones of the shot.', '2007-10-04 21:24:44.000000', NULL, 1),
(4142471, 592674, 6179, '<td valign="top">Excellent macro shot.</td>', 'Excellent macro shot.', '2007-10-04 21:25:22.000000', NULL, 1),
