(4148245, 594037, 79021, '<td valign="top">Great shot but the cars at the end of the road detracts from the impact</td>', 'Great shot but the cars at the end of the road detracts from the impact', '2007-10-07 00:31:51.000000', NULL, 1),
(4148250, 593671, 79021, '<td valign="top">I''m guessing this will be one of the top entries</td>', 'I''m guessing this will be one of the top entries', '2007-10-07 00:32:26.000000', NULL, 1),
(4148281, 587058, 25787, '<td valign="top">I think more postprocessing would have helped this picture a lot.  Composition is good</td>', 'I think more postprocessing would have helped this picture a lot.  Composition is good', '2007-10-07 00:46:36.000000', NULL, 1),
