(4149151, 593899, 66616, '<td valign="top">Beautiful colours.</td>', 'Beautiful colours.', '2007-10-07 13:43:16.000000', NULL, 1),
(4149159, 592729, 55956, '<td valign="top">very good still life, if the curve in the first glass was aligned with the bottle was perfect! 9</td>', 'very good still life, if the curve in the first glass was aligned with the bottle was perfect! 9', '2007-10-07 13:45:33.000000', NULL, 1),
