(4149858, 583581, 50695, '<td valign="top">I don''t generally go for pop culture imitations, but this is so quirky I gotta love it.</td>', 'I don''t generally go for pop culture imitations, but this is so quirky I gotta love it.', '2007-10-07 19:18:10.000000', NULL, 1),
(4149859, 593553, 50695, '<td valign="top">Nice tableau. You''re probably getting dinged for those splotches of light, but that''s my favorite part.</td>', 'Nice tableau. You''re probably getting dinged for those splotches of light, but that''s my favorite part.', '2007-10-07 19:19:02.000000', NULL, 1),
(4149861, 587569, 50695, '<td valign="top">I''ve never seen him from this angle before. Great capture. The composition seems a little off, though, or too "on"</td>', 'I''ve never seen him from this angle before. Great capture. The composition seems a little off, though, or too "on"', '2007-10-07 19:20:03.000000', NULL, 1),
(4149862, 592684, 50695, '<td valign="top">remarkable capture.</td>', 'remarkable capture.', '2007-10-07 19:20:18.000000', NULL, 1),
(4149863, 588605, 50695, '<td valign="top">transformative.</td>', 'transformative.', '2007-10-07 19:20:38.000000', NULL, 1),
(4149864, 594084, 50695, '<td valign="top">well done! how much camera and how much processing? It looks splendid.</td>', 'well done! how much camera and how much processing? It looks splendid.', '2007-10-07 19:21:07.000000', NULL, 1),
(4149865, 592860, 50695, '<td valign="top">I love the lighting. Not only does it look like the 70s. It looks like film.</td>', 'I love the lighting. Not only does it look like the 70s. It looks like film.', '2007-10-07 19:21:13.000000', NULL, 1),
(4149866, 592149, 50695, '<td valign="top">remarkable effect. can''t wait to hear how you did it.</td>', 'remarkable effect. can''t wait to hear how you did it.', '2007-10-07 19:21:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4149869, 585397, 50695, '<td valign="top">I don''t like the reflection a ringlight makes in the eyes, but otherwise this picture is just bizarre enough to be interesting.</td>', 'I don''t like the reflection a ringlight makes in the eyes, but otherwise this picture is just bizarre enough to be interesting.', '2007-10-07 19:23:10.000000', NULL, 1),
(4149871, 591901, 50695, '<td valign="top">Nice composition and the boat integrates into it nicely.</td>', 'Nice composition and the boat integrates into it nicely.', '2007-10-07 19:23:35.000000', NULL, 1),
(4149873, 592114, 50695, '<td valign="top">I loooove this lighting and the shallow dof. colors are great, too.</td>', 'I loooove this lighting and the shallow dof. colors are great, too.', '2007-10-07 19:25:00.000000', NULL, 1),
(4149875, 590303, 50695, '<td valign="top">nice colors and darkness, good use of "natural" framing.</td>', 'nice colors and darkness, good use of "natural" framing.', '2007-10-07 19:25:30.000000', NULL, 1),
(4149876, 593714, 50695, '<td valign="top">this is musical and fanciful. Lovely.</td>', 'this is musical and fanciful. Lovely.', '2007-10-07 19:25:55.000000', NULL, 1),
(4149877, 593321, 50695, '<td valign="top">strange, mysterious image.</td>', 'strange, mysterious image.', '2007-10-07 19:26:20.000000', NULL, 1),
(4149878, 592846, 50695, '<td valign="top">post-apocalyptic.</td>', 'post-apocalyptic.', '2007-10-07 19:26:42.000000', NULL, 1),
(4149879, 593741, 50695, '<td valign="top">remarkable capture.</td>', 'remarkable capture.', '2007-10-07 19:26:58.000000', NULL, 1),
(4149880, 590290, 50695, '<td valign="top">love the cinematic sentimentality. Scorsese would like this.</td>', 'love the cinematic sentimentality. Scorsese would like this.', '2007-10-07 19:27:40.000000', NULL, 1),
(4149881, 593466, 50695, '<td valign="top">just weird enough to keep me interested. cool.</td>', 'just weird enough to keep me interested. cool.', '2007-10-07 19:28:00.000000', NULL, 1),
(4149882, 593754, 50695, '<td valign="top">I find the vignetting a little distracting but still a great candid(?) portrait.</td>', 'I find the vignetting a little distracting but still a great candid(?) portrait.', '2007-10-07 19:29:06.000000', NULL, 1),
(4149885, 591620, 50695, '<td valign="top">Not just a wild and provocative photo, a great babysitting idea!</td>', 'Not just a wild and provocative photo, a great babysitting idea!', '2007-10-07 19:29:48.000000', NULL, 1),
(4149887, 593354, 78388, '<td valign="top">Fantastic shot, feels like a painting.</td>', 'Fantastic shot, feels like a painting.', '2007-10-07 19:30:01.000000', NULL, 1),
(4149889, 585837, 50695, '<td valign="top">I think you might have gotten the "decisive moment" here. I wonder if the crop is right, though.</td>', 'I think you might have gotten the "decisive moment" here. I wonder if the crop is right, though.', '2007-10-07 19:30:28.000000', NULL, 1),
(4149895, 589209, 50695, '<td valign="top">I feel as though this was a young couple who made deeply felt vows, touched the bouquet and instantly grew old together, like they were so eager to give their lives to each other that they did, all at once. This photo haunts me.</td>', 'I feel as though this was a young couple who made deeply felt vows, touched the bouquet and instantly grew old together, like they were so eager to give their lives to each other that they did, all at once. This photo haunts me.', '2007-10-07 19:31:59.000000', NULL, 1),
(4149897, 589684, 50695, '<td valign="top">7 for getting a shadow on the sky.</td>', '7 for getting a shadow on the sky.', '2007-10-07 19:32:23.000000', NULL, 1),
(4149898, 593320, 50695, '<td valign="top">upside-down shoe and the luck runs out. Nice composition.</td>', 'upside-down shoe and the luck runs out. Nice composition.', '2007-10-07 19:32:46.000000', NULL, 1),
(4149899, 591743, 78388, '<td valign="top">This looks over sharpened - perhaps too extreme a crop?</td>', 'This looks over sharpened - perhaps too extreme a crop?', '2007-10-07 19:33:20.000000', NULL, 1),
(4149900, 593455, 50695, '<td valign="top">I like the strong composition elements almost hidden in the business of the background. Cool photo.</td>', 'I like the strong composition elements almost hidden in the business of the background. Cool photo.', '2007-10-07 19:33:34.000000', NULL, 1),
(4149901, 593809, 50695, '<td valign="top">Nice environmental portrait. they truly seem like they are in their element.</td>', 'Nice environmental portrait. they truly seem like they are in their element.', '2007-10-07 19:34:25.000000', NULL, 1),
(4149902, 594049, 50695, '<td valign="top">commanding composition. I hate old car shots. But this is not an old car shot. This is a photograph.</td>', 'commanding composition. I hate old car shots. But this is not an old car shot. This is a photograph.', '2007-10-07 19:35:30.000000', NULL, 1),
(4149903, 594028, 50695, '<td valign="top">That single car in the foreground really tells a story. Love your title, too.</td>', 'That single car in the foreground really tells a story. Love your title, too.', '2007-10-07 19:36:13.000000', NULL, 1),
(4149904, 593267, 50695, '<td valign="top">The strangeness of this photo sneaks up on you. I keep wondering if there were other things you could have done to make the reflection seem a little out of wack. Still, much enjoyed.</td>', 'The strangeness of this photo sneaks up on you. I keep wondering if there were other things you could have done to make the reflection seem a little out of wack. Still, much enjoyed.', '2007-10-07 19:37:04.000000', NULL, 1),
(4149905, 591187, 50695, '<td valign="top">good visual storytelling.</td>', 'good visual storytelling.', '2007-10-07 19:37:17.000000', NULL, 1),
(4149906, 592990, 50695, '<td valign="top">yikes. good special effects!</td>', 'yikes. good special effects!', '2007-10-07 19:37:35.000000', NULL, 1),
(4149907, 592520, 50695, '<td valign="top">this really grows on me. It''s like an attempt to go back in time, and whether it fails or not is ultimately unimportant.</td>', 'this really grows on me. It''s like an attempt to go back in time, and whether it fails or not is ultimately unimportant.', '2007-10-07 19:38:20.000000', NULL, 1),
(4149909, 591641, 50695, '<td valign="top">Jeffrey, is that you? I hope so. I''m not willing to say that YOU have got my number just yet, but this photo certainly does.</td>', 'Jeffrey, is that you? I hope so. I''m not willing to say that YOU have got my number just yet, but this photo certainly does.', '2007-10-07 19:38:46.000000', NULL, 1),
(4149910, 591882, 50695, '<td valign="top">I like the amorphous train and the small dark huddle of people: a bold composition.</td>', 'I like the amorphous train and the small dark huddle of people: a bold composition.', '2007-10-07 19:39:29.000000', NULL, 1),
(4149994, 593466, 23484, '<td valign="top">Cool processing.</td>', 'Cool processing.', '2007-10-07 20:37:52.000000', NULL, 1),
(4149995, 591639, 164, '<td valign="top">too dark</td>', 'too dark', '2007-10-07 20:38:06.000000', NULL, 1),
(4149997, 589327, 23484, '<td valign="top">Cool shot but too out of focus.</td>', 'Cool shot but too out of focus.', '2007-10-07 20:38:47.000000', NULL, 1),
(4150001, 594091, 23484, '<td valign="top">Great job.</td>', 'Great job.', '2007-10-07 20:39:33.000000', NULL, 1),
(4150002, 593907, 23484, '<td valign="top">Neat shot. I really like the patterns.</td>', 'Neat shot. I really like the patterns.', '2007-10-07 20:39:55.000000', NULL, 1),
(4150067, 590290, 79021, '<td valign="top">Very well composed (the bit of knee missing doesnt take away from the image).  The right side of the shot fading into the almost complete blackness on the left works very well with his expression in setting the mood.  The only thing I felt was missing was some kind of hand guards/wraps/gloves since, to me anyway, it looks like he is reflecting on a lost fight.  Other than that this is one of my top picks for the challenge</td>', 'Very well composed (the bit of knee missing doesnt take away from the image).  The right side of the shot fading into the almost complete blackness on the left works very well with his expression in setting the mood.  The only thing I felt was missing was some kind of hand guards/wraps/gloves since, to me anyway, it looks like he is reflecting on a lost fight.  Other than that this is one of my top picks for the challenge', '2007-10-07 21:28:59.000000', NULL, 1),
(4150069, 593612, 67697, '<td valign="top">Great close up, great catc!  Love the clarity on its face.  So cute!</td>', 'Great close up, great catc!  Love the clarity on its face.  So cute!', '2007-10-07 21:30:35.000000', NULL, 1),
(4150070, 593267, 73505, '<td valign="top">Love the idea of the photo. wish the girls make-up wasn''t so over done. it takes from the shot. otherwise, I like it alot.</td>', 'Love the idea of the photo. wish the girls make-up wasn''t so over done. it takes from the shot. otherwise, I like it alot.', '2007-10-07 21:31:04.000000', NULL, 1),
(4150071, 594004, 67697, '<td valign="top">Beautiful find, especially with them being on the green and white striped leaf.</td>', 'Beautiful find, especially with them being on the green and white striped leaf.', '2007-10-07 21:31:18.000000', NULL, 1),
(4150072, 592496, 73505, '<td valign="top">love the fall colors!</td>', 'love the fall colors!', '2007-10-07 21:31:57.000000', NULL, 1),
(4150073, 593176, 67697, '<td valign="top">I like how this is a different kind of children''s shot.  Love the eyes and the candidness of the pic.  Quite striking and really catches your attention.</td>', 'I like how this is a different kind of children''s shot.  Love the eyes and the candidness of the pic.  Quite striking and really catches your attention.', '2007-10-07 21:32:28.000000', NULL, 1),
(4150074, 592266, 67697, '<td valign="top">Very pretty sky colors.  Love the lone cloud in the pic.</td>', 'Very pretty sky colors.  Love the lone cloud in the pic.', '2007-10-07 21:33:20.000000', NULL, 1),
(4150076, 593351, 67697, '<td valign="top">Awesome.  Great use of geometrics to bring my eyes into the depth of the pic.  Looks great in black and white!</td>', 'Awesome.  Great use of geometrics to bring my eyes into the depth of the pic.  Looks great in black and white!', '2007-10-07 21:34:20.000000', NULL, 1),
(4150077, 593688, 73505, '<td valign="top">Love the expression on the cat''s face. He/she doesn''t look happy! cute shot!</td>', 'Love the expression on the cat''s face. He/she doesn''t look happy! cute shot!', '2007-10-07 21:34:36.000000', NULL, 1),
(4150079, 593340, 67697, '<td valign="top">Love the colors and composition.  My preference is to see a sharper focus on the leaf.</td>', 'Love the colors and composition.  My preference is to see a sharper focus on the leaf.', '2007-10-07 21:35:17.000000', NULL, 1),
(4150082, 593350, 67697, '<td valign="top">This looks like it would be a wonderful place to see in person.  I am not a big fan of the kind of processing you used on the building.  I guess when I see architecture, I like seeing the crisp lines.</td>', 'This looks like it would be a wonderful place to see in person.  I am not a big fan of the kind of processing you used on the building.  I guess when I see architecture, I like seeing the crisp lines.', '2007-10-07 21:36:55.000000', NULL, 1),
(4150085, 592985, 73505, '<td valign="top">WOW! Great cloe-up!</td>', 'WOW! Great cloe-up!', '2007-10-07 21:37:49.000000', NULL, 1),
(4150087, 593938, 67697, '<td valign="top">I like the title lol.  Love how the white head just pops in this pic.</td>', 'I like the title lol.  Love how the white head just pops in this pic.', '2007-10-07 21:38:28.000000', NULL, 1),
(4150091, 593389, 67697, '<td valign="top">That''s cool - the perspective is quite dizzying.  I love how you made it look like the lights are about as tall as the top of the space needle?  (guessing that is what this is).</td>', 'That''s cool - the perspective is quite dizzying.  I love how you made it look like the lights are about as tall as the top of the space needle?  (guessing that is what this is).', '2007-10-07 21:39:46.000000', NULL, 1),
(4150093, 593603, 67697, '<td valign="top">That''s cool, I''ve never seen balloons come down and touch the water like this.  Love the reflections.</td>', 'That''s cool, I''ve never seen balloons come down and touch the water like this.  Love the reflections.', '2007-10-07 21:41:10.000000', NULL, 1),
(4150098, 593703, 67697, '<td valign="top">I bet this was something quite beautiful to see.  The sky is too saturated - there''s this funky bright border between the mountain ridge and the sky.  Also there''s a halo around some of the balloons.  (5)</td>', 'I bet this was something quite beautiful to see.  The sky is too saturated - there''s this funky bright border between the mountain ridge and the sky.  Also there''s a halo around some of the balloons.  (5)', '2007-10-07 21:42:33.000000', NULL, 1),
(4150101, 582881, 67697, '<td valign="top">A very sweet and candid moment.  So cute!</td>', 'A very sweet and candid moment.  So cute!', '2007-10-07 21:42:52.000000', NULL, 1),
(4150102, 589513, 67697, '<td valign="top">Very cool, I''ve never seen it from this perspective before.  The sky is beautiful!</td>', 'Very cool, I''ve never seen it from this perspective before.  The sky is beautiful!', '2007-10-07 21:43:24.000000', NULL, 1),
(4150105, 584617, 67697, '<td valign="top">If she just had this baby, I hate her lol.  She looks great!  This is an AWESOME photo and such a different take for a mom/child shot.</td>', 'If she just had this baby, I hate her lol.  She looks great!  This is an AWESOME photo and such a different take for a mom/child shot.', '2007-10-07 21:44:36.000000', NULL, 1),
(4150107, 592234, 67697, '<td valign="top">I like photos like these.  They make you want to either know the back story or what is going to happen next.  The black and white looks great!</td>', 'I like photos like these.  They make you want to either know the back story or what is going to happen next.  The black and white looks great!', '2007-10-07 21:45:15.000000', NULL, 1),
(4150111, 591187, 67697, '<td valign="top">Hmmm - I have mixed feelings on this.  I love the symbolism here, especially with the person being opaque.  But it just seems to interrupt a very beautiful background.  7</td>', 'Hmmm - I have mixed feelings on this.  I love the symbolism here, especially with the person being opaque.  But it just seems to interrupt a very beautiful background.  7', '2007-10-07 21:49:54.000000', NULL, 1),
(4150112, 593942, 67697, '<td valign="top">Great closeup - you can really see some of the focus and intensity in the eyes.</td>', 'Great closeup - you can really see some of the focus and intensity in the eyes.', '2007-10-07 21:50:32.000000', NULL, 1),
(4150114, 593740, 67697, '<td valign="top">She looks almost like Alanis Morisette.  I don''t understand why you would hide her face behind the hair like that.  I don''t really do portraits so maybe that''s the thing to do now.  Love how you brought out the color of her eyes.</td>', 'She looks almost like Alanis Morisette.  I don''t understand why you would hide her face behind the hair like that.  I don''t really do portraits so maybe that''s the thing to do now.  Love how you brought out the color of her eyes.', '2007-10-07 21:51:52.000000', NULL, 1),
(4150115, 593981, 67697, '<td valign="top">This is cool.  I love how it looks like it is coming right at you.</td>', 'This is cool.  I love how it looks like it is coming right at you.', '2007-10-07 21:52:23.000000', NULL, 1),
(4150117, 591641, 79021, '<td valign="top">overexposed and blurry</td>', 'overexposed and blurry', '2007-10-07 21:53:19.000000', NULL, 1),
(4150121, 593628, 79021, '<td valign="top">What is the black object in the middle of the bowl?  Nice use of blacks and whites.</td>', 'What is the black object in the middle of the bowl?  Nice use of blacks and whites.', '2007-10-07 21:55:22.000000', NULL, 1),
(4150124, 585552, 67697, '<td valign="top">Great concept but there are some distractions for me.  The light is too bright on the whites for my taste and I would like to have seen the hands in focus.  5</td>', 'Great concept but there are some distractions for me.  The light is too bright on the whites for my taste and I would like to have seen the hands in focus.  5', '2007-10-07 21:55:57.000000', NULL, 1),
(4150125, 593754, 67697, '<td valign="top">Great candid.  I love his stare.  He doesn''t really seem to be laughing all that much lol.</td>', 'Great candid.  I love his stare.  He doesn''t really seem to be laughing all that much lol.', '2007-10-07 21:57:30.000000', NULL, 1),
(4150126, 584617, 79021, '<td valign="top">I think some of the curve is lost with the lighing on the legs.  I would have liked to have seen the same lighting as on the arm, where most of the arm is lit but then fades into darkness...</td>', 'I think some of the curve is lost with the lighing on the legs.  I would have liked to have seen the same lighting as on the arm, where most of the arm is lit but then fades into darkness...', '2007-10-07 21:57:32.000000', NULL, 1),
(4150127, 593568, 67697, '<td valign="top">Sooooo pretty.  Love the combination of a water droplet and a feather.  Love the soft light on this as well.</td>', 'Sooooo pretty.  Love the combination of a water droplet and a feather.  Love the soft light on this as well.', '2007-10-07 21:58:46.000000', NULL, 1),
(4150128, 593884, 79021, '<td valign="top">Check the recent forum about adding textures.  I don''t think this shot alone is very powerful, but a texture overlay may bring it to life...4</td>', 'Check the recent forum about adding textures.  I don''t think this shot alone is very powerful, but a texture overlay may bring it to life...4', '2007-10-07 21:59:14.000000', NULL, 1),
(4150129, 592885, 67697, '<td valign="top">Love the fog.  Looks like you had great lighting for this kind of scene.</td>', 'Love the fog.  Looks like you had great lighting for this kind of scene.', '2007-10-07 21:59:31.000000', NULL, 1),
(4150132, 593675, 67697, '<td valign="top">Really really cool.  The sky is awesome.  I love the lit up tree too.</td>', 'Really really cool.  The sky is awesome.  I love the lit up tree too.', '2007-10-07 22:00:32.000000', NULL, 1),
(4150135, 593973, 79021, '<td valign="top">This shot has been overdone, especially with flowers.  Its a nice shot, but why not look at what others have done with  these drop shots and make one that is unique?</td>', 'This shot has been overdone, especially with flowers.  Its a nice shot, but why not look at what others have done with  these drop shots and make one that is unique?', '2007-10-07 22:01:22.000000', NULL, 1),
(4150137, 593261, 67697, '<td valign="top">I''m jealous.  I''ve been to Seattle 3 times and each time Mt. Rainier was covered in clouds.  Great catch!</td>', 'I''m jealous.  I''ve been to Seattle 3 times and each time Mt. Rainier was covered in clouds.  Great catch!', '2007-10-07 22:01:45.000000', NULL, 1),
(4150138, 593816, 35804, '<td valign="top">Ah! So lovely...the broken wings are the perfect addition to an already intriguing composition.</td>', 'Ah! So lovely...the broken wings are the perfect addition to an already intriguing composition.', '2007-10-07 22:01:58.000000', NULL, 1),
(4150141, 584360, 35804, '<td valign="top">A nice one at that! Very nice.</td>', 'A nice one at that! Very nice.', '2007-10-07 22:02:58.000000', NULL, 1),
(4150143, 593806, 79021, '<td valign="top">I thinking having the model to the left of the middle doesn''t work so well with the "hide" title.  For me, I think it would be more fitting for the model to be in the lower righthand corner</td>', 'I thinking having the model to the left of the middle doesn''t work so well with the "hide" title.  For me, I think it would be more fitting for the model to be in the lower righthand corner', '2007-10-07 22:03:27.000000', NULL, 1),
(4150144, 593232, 67697, '<td valign="top">Evil dog!  Go get the bad water!  Hehe - funny catch.  Hope he got something to drink!</td>', 'Evil dog!  Go get the bad water!  Hehe - funny catch.  Hope he got something to drink!', '2007-10-07 22:03:36.000000', NULL, 1),
(4150145, 591170, 67697, '<td valign="top">Love the moody blue tones.  Great lighting on the water and I love the sky!</td>', 'Love the moody blue tones.  Great lighting on the water and I love the sky!', '2007-10-07 22:03:59.000000', NULL, 1),
(4150146, 592752, 35804, '<td valign="top">The three little ones follow the big one across the frame. I love the shallow DOF and color...very nice.</td>', 'The three little ones follow the big one across the frame. I love the shallow DOF and color...very nice.', '2007-10-07 22:04:49.000000', NULL, 1),
(4150148, 589743, 35804, '<td valign="top">Perfectly elegant...I can nearly hear the stillness.</td>', 'Perfectly elegant...I can nearly hear the stillness.', '2007-10-07 22:05:45.000000', NULL, 1),
(4150149, 593269, 79021, '<td valign="top">perfect reflection.  I think some more intense white clouds would have added very nicely to the reflection (of course you have no control of that)</td>', 'perfect reflection.  I think some more intense white clouds would have added very nicely to the reflection (of course you have no control of that)', '2007-10-07 22:05:46.000000', NULL, 1),
(4150153, 593796, 79021, '<td valign="top">The textures work very well together</td>', 'The textures work very well together', '2007-10-07 22:07:23.000000', NULL, 1),
(4150155, 593203, 79021, '<td valign="top">disturbing but definitely different</td>', 'disturbing but definitely different', '2007-10-07 22:09:06.000000', NULL, 1),
(4150162, 593703, 79021, '<td valign="top">Maybe its my eyes or my monitor but it looks like there is CA around the mountain and all of the balloons</td>', 'Maybe its my eyes or my monitor but it looks like there is CA around the mountain and all of the balloons', '2007-10-07 22:11:47.000000', NULL, 1),
(4150164, 594042, 79021, '<td valign="top">The lighting on the back reveals the tattoo, which I think is somewhat distracting</td>', 'The lighting on the back reveals the tattoo, which I think is somewhat distracting', '2007-10-07 22:13:14.000000', NULL, 1),
(4150171, 593244, 35804, '<td valign="top">Love the look and atmosphere of this shot...very nice.</td>', 'Love the look and atmosphere of this shot...very nice.', '2007-10-07 22:16:16.000000', NULL, 1),
(4150178, 593478, 35804, '<td valign="top">So pleasing to look at and study...all that texture and vibrant color, very nice.</td>', 'So pleasing to look at and study...all that texture and vibrant color, very nice.', '2007-10-07 22:20:28.000000', NULL, 1),
(4150181, 590376, 35804, '<td valign="top">An enjoyable abstract to be sure...nicely seen.</td>', 'An enjoyable abstract to be sure...nicely seen.', '2007-10-07 22:22:30.000000', NULL, 1),
(4150186, 588773, 35804, '<td valign="top">Nice POV and love the deep rich colors.</td>', 'Nice POV and love the deep rich colors.', '2007-10-07 22:26:17.000000', NULL, 1),
